import fs from 'node:fs';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';

const base = '/workspace/luxestyle-review/tagespruefung-20261028';
const before = await import(pathToFileURL(`${base}/merchant/before/automation/lib/gmc_feed_item.mjs`).href);
const fixture = {
  id:'existing-merchant-id', handle:'testprodukt', titel:'Deko-Leuchte',
  beschreibung:'Dekorative Leuchte.', preis:'34.90', waehrung:'CHF',
  link:'https://luxestyle.ch/products/testprodukt',
  bild:'https://cdn.shopify.com/s/files/1/test/leuchte.jpg',
  tags:['cj-real'], verfuegbar:true, excludedDestinations:[],
};
const source = fs.readFileSync(`${base}/merchant/before/automation/lib/gmc_feed_item.mjs`,'utf8');
const baseline = [
  {name:'missing identifiers become asserted absent', found:before.feedItem(fixture).includes('<g:identifier_exists>no</g:identifier_exists>')},
  {name:'Shopping_ads exclusion omitted', found:!before.feedItem({...fixture,excludedDestinations:['Shopping_ads']}).includes('<g:excluded_destination>Shopping_ads</g:excluded_destination>')},
  {name:'unknown availability becomes in stock', found:before.feedItem({...fixture,verfuegbar:undefined}).includes('<g:availability>in stock</g:availability>')},
  {name:'merchant SKU used as manufacturer MPN', found:before.feedItem({...fixture,sku:'CJ-123'}).includes('<g:mpn>CJ-123</g:mpn>')},
  {name:'seller name invented as manufacturer brand', found:before.feedItem(fixture).includes('<g:brand>LuxeStyle</g:brand>')},
];
for(const p of baseline) assert.equal(p.found,true,p.name);
const result={checkedAt:new Date().toISOString(),scope:'Independent offline item probes; no API/network/writes except this report',baseline,checksPassed:baseline.length};
const fixedPath=`${base}/merchant/after/automation/lib/gmc_feed_item.mjs`;
if(fs.existsSync(fixedPath)) {
  const after=await import(pathToFileURL(fixedPath).href);
  let count=0;
  const check=(condition,name)=>{assert.ok(condition,name);count++;};
  const rejects=(p,name)=>{assert.throws(()=>after.feedItem(p),undefined,name);count++;};
  const xml=after.feedItem(fixture);
  check(!xml.includes('<g:identifier_exists>'),'unknown UPI absence omitted');
  check(!xml.includes('<g:brand>'),'unproven default seller-brand omitted');
  check(!after.feedItem({...fixture,sku:'CJ-123'}).includes('<g:mpn>'),'retailer SKU omitted as MPN');
  check(after.feedItem({...fixture,excludedDestinations:['Shopping_ads']}).includes('<g:excluded_destination>Shopping_ads</g:excluded_destination>'),'Shopping_ads preserved');
  check(!after.feedItem({...fixture,excludedDestinations:['Shopping_ads']}).includes('<g:excluded_destination>Free_listings</g:excluded_destination>'),'Shopping_ads does not imply Free_listings');
  const both=after.feedItem({...fixture,excludedDestinations:['Shopping_ads','Free_listings']});
  check(both.includes('<g:excluded_destination>Shopping_ads</g:excluded_destination>') && both.includes('<g:excluded_destination>Free_listings</g:excluded_destination>'),'both independent exclusions preserved');
  for(const value of [undefined,null,0,1,'false','true']) rejects({...fixture,verfuegbar:value},`unknown availability ${String(value)}`);
  for(const value of [undefined,null,'Shopping_ads',['unknown'],['Shopping_ads',null]]) rejects({...fixture,excludedDestinations:value},`malformed exclusions ${JSON.stringify(value)}`);
  // Empty-tag source completeness is checked by the generator; the shared
  // legacy safety filter must stay unchanged for its other consumers.
  check(after.feedItem({...fixture,verfuegbar:false}).includes('<g:availability>out of stock</g:availability>'),'explicit false preserved');
  check(after.feedItem({...fixture,verfuegbar:true}).includes('<g:availability>in stock</g:availability>'),'explicit true preserved');
  check(after.feedItem({...fixture,tags:['cj-real','rueckhol-0907']})!==null,'social-only rueckhol restriction not broadened into Merchant policy');
  const shared=(s)=>s.slice(s.indexOf('export function pruefeProdukt'),s.indexOf('\n/**\n * Baut den'));
  check(shared(source)===shared(fs.readFileSync(fixedPath,'utf8')),'shared safety filter byte unchanged');
  result.fixed={checksPassed:count};
}
fs.writeFileSync(`${base}/review/MERCHANT-INDEPENDENT-PROBES.json`,JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify(result));

import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';

const base='/workspace/luxestyle-review/tagespruefung-20261028';
const {runMerchantFeed,SHOP_QUERY,PAGE_QUERY}=await import(pathToFileURL(`${base}/merchant/after/automation/autopilot/merchant_feed.mjs`).href);
const record=n=>({productId:`gid://shopify/Product/${n}`,variantId:`gid://shopify/ProductVariant/${n+100}`,handle:`test-${n}`,feedId:`OLD-OPAQUE-${n}`});
const product=n=>({id:record(n).productId,status:'ACTIVE',title:'Schlichte Deko',handle:record(n).handle,onlineStoreUrl:`https://luxestyle.ch/products/test-${n}`,vendor:'LuxeStyle',productType:'Deko',tags:['cj-real'],beschreibung:'Schlichte Dekoration.',featuredMedia:{mediaContentType:'IMAGE',image:{url:'https://cdn.shopify.com/fixture.jpg'}},media:{edges:[]},excludedDestination:null,googleKategorie:null,altersgruppe:null,geschlecht:null,zustand:null,variants:{pageInfo:{hasNextPage:false},edges:[{node:{id:record(n).variantId,sku:'CJ-MERCHANT-SKU',price:'59.90',compareAtPrice:null,availableForSale:true,barcodes:{pageInfo:{hasNextPage:false},edges:[]}}}]}});
const map={version:1,shopDomain:'luxestyle.ch',merchantAccountId:'5797470070',idPolicy:'preserve-existing',complete:true,dataSourceId:'OFFLINE-NOT-AN-ACTUAL-SOURCE',sourceSnapshotSha256:'a'.repeat(64),reviewReference:'SYNTHETIC REVIEW FIXTURE ONLY',entries:[record(1),record(2)]};
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'luxe-whole-candidate-'));const mapFile=path.join(dir,'map.json'),output=path.join(dir,'candidate.xml');fs.writeFileSync(mapFile,JSON.stringify(map));
const checks=[];let networkCalls=0;const savedFetch=globalThis.fetch;globalThis.fetch=async()=>{networkCalls++;throw Error('NETWORK FORBIDDEN');};
try {
 const invalid=[
  ['missing second exclusion field',p=>delete p.excludedDestination],
  ['malformed second exclusion',p=>{p.excludedDestination={type:'list.single_line_text_field',value:'["Shopping_ads",null]'};}],
  ['unknown second availability',p=>{delete p.variants.edges[0].node.availableForSale;}],
  ['truncated second barcode connection',p=>{p.variants.edges[0].node.barcodes.pageInfo.hasNextPage=true;}],
  ['second product has unreviewed multiple variants',p=>{p.variants.pageInfo.hasNextPage=true;}],
  ['second product tags empty',p=>{p.tags=[];}],
  ['second product tag list missing',p=>{delete p.tags;}],
  ['second product now safety blocked',p=>{p.tags=['cj-real','nicht-bewerben'];}],
 ];
 for(const [name,alter] of invalid) {
  fs.writeFileSync(output,'PREVIOUS COMPLETE CANDIDATE');const first=product(1),second=product(2);alter(second);let writes=0;
  await assert.rejects(runMerchantFeed({env:{FEED_IDENTITY_MAP:mapFile,OUT:output,FEED_ALLOW_REPLACE:'1',SHOPIFY_ADMIN_TOKEN:'OFFLINE-FAKE-NOT-A-CREDENTIAL'},gql:async(_shop,_api,_token,query)=>query===SHOP_QUERY?{shop:{myshopifyDomain:'au3j0y-hq.myshopify.com',currencyCode:'CHF',primaryDomain:{url:'https://luxestyle.ch'}}}:{products:{edges:[{node:first},{node:second}],pageInfo:{hasNextPage:false,endCursor:null}}},write:()=>{writes++;}}));
  assert.equal(writes,0);assert.equal(fs.readFileSync(output,'utf8'),'PREVIOUS COMPLETE CANDIDATE');checks.push({name,result:'PASS',priorOutputPreserved:true});
 }
 const second=product(2);second.beschreibung='Neutraler Text. '.repeat(100)+'Harry Potter';let writes=0;
 await assert.rejects(runMerchantFeed({env:{FEED_IDENTITY_MAP:mapFile,OUT:output,FEED_ALLOW_REPLACE:'1',SHOPIFY_ADMIN_TOKEN:'OFFLINE-FAKE-NOT-A-CREDENTIAL'},gql:async(_shop,_api,_token,query)=>query===SHOP_QUERY?{shop:{myshopifyDomain:'au3j0y-hq.myshopify.com',currencyCode:'CHF',primaryDomain:{url:'https://luxestyle.ch'}}}:{products:{edges:[{node:product(1)},{node:second}],pageInfo:{hasNextPage:false,endCursor:null}}},write:()=>{writes++;}}),/Lizenzname/);
 assert.equal(writes,0);assert.ok(!/beschreibung:\s*description\s*\(\s*truncateAt/.test(PAGE_QUERY),'policy review requires full source description');checks.push({name:'late licensed name after900 chars reaches filter before XML truncation',result:'PASS'});
 assert.equal(networkCalls,0);const result={checkedAt:new Date().toISOString(),scope:'Independent mixed-valid-invalid two-item candidate probes with synthetic source map; no production-source approval',checks,checksPassed:checks.length,networkCalls,liveWrites:0};fs.writeFileSync(`${base}/review/MERCHANT-WHOLE-CANDIDATE-PROBES.json`,JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));
}finally{globalThis.fetch=savedFetch;fs.rmSync(dir,{recursive:true,force:true});}

import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import os from 'node:os';
import { pathToFileURL } from 'node:url';

const base='/workspace/luxestyle-review/tagespruefung-20261028';
const modulePath=`${base}/merchant/after/automation/autopilot/merchant_feed.mjs`;
const savedFetch=globalThis.fetch;
let networkCalls=0;
globalThis.fetch=async()=>{networkCalls++;throw Error('network forbidden in independent review');};
const merchant=await import(pathToFileURL(modulePath).href);
assert.equal(networkCalls,0,'module import must not fetch');
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'luxe-merchant-independent-'));
const checks=[];
const ok=name=>checks.push({name,result:'PASS'});
try {
 const existing=path.join(dir,'existing.xml');fs.writeFileSync(existing,'EXISTING');
 assert.throws(()=>merchant.writeCandidate(existing,'REPLACEMENT'),/FEED_OUTPUT_EXISTS/);
 assert.equal(fs.readFileSync(existing,'utf8'),'EXISTING');ok('existing output preserved by default');

 const race=path.join(dir,'race.xml'),savedLink=fs.linkSync;
 fs.linkSync=(from,to)=>{if(to===race)fs.writeFileSync(race,'CONCURRENT FOREIGN OUTPUT',{flag:'wx'});return savedLink(from,to);};
 try{assert.throws(()=>merchant.writeCandidate(race,'REPLACEMENT'),/FEED_OUTPUT_EXISTS/);}finally{fs.linkSync=savedLink;}
 assert.equal(fs.readFileSync(race,'utf8'),'CONCURRENT FOREIGN OUTPUT');ok('racing output atomically preserved');
 assert.ok(!fs.existsSync(`${race}.tmp-${process.pid}`));ok('owned race temp removed');

 const broken=path.join(dir,'broken.xml');fs.symlinkSync(path.join(dir,'absent.xml'),broken);
 assert.throws(()=>merchant.writeCandidate(broken,'REPLACEMENT'),/FEED_OUTPUT_EXISTS/);
 assert.ok(fs.lstatSync(broken).isSymbolicLink());ok('broken output symlink not overwritten');

 merchant.writeCandidate(existing,'APPROVED REPLACEMENT',{allowReplace:true});
 assert.equal(fs.readFileSync(existing,'utf8'),'APPROVED REPLACEMENT');ok('explicit replacement stays supported');

 const mapFile=path.join(dir,'identity-map.json');const map={version:1,shopDomain:'luxestyle.ch',merchantAccountId:'5797470070',idPolicy:'preserve-existing',complete:true,dataSourceId:'offline-fixture-only',sourceSnapshotSha256:'a'.repeat(64),reviewReference:'offline-test; not a real source',entries:[{productId:'gid://shopify/Product/1',variantId:'gid://shopify/ProductVariant/11',handle:'fixture-product',feedId:'EXISTING-ID'}]};
 fs.writeFileSync(mapFile,JSON.stringify(map));const source=fs.readFileSync(mapFile,'utf8');
 const hard=path.join(dir,'map-hard.json');fs.linkSync(mapFile,hard);
 const sym=path.join(dir,'map-link.json');fs.symlinkSync(mapFile,sym);
 for(const target of [mapFile,hard,sym]) {
  await assert.rejects(merchant.runMerchantFeed({env:{FEED_IDENTITY_MAP:mapFile,OUT:target,FEED_ALLOW_REPLACE:'1'},gql:async()=>{throw Error('gql forbidden');}}),/FEED_OUTPUT_ALIAS/);
  assert.equal(fs.readFileSync(mapFile,'utf8'),source);ok(`identity-map alias blocked: ${path.basename(target)}`);
 }
 assert.equal(networkCalls,0);ok('all output preflights happen before token/network');
 const report={checkedAt:new Date().toISOString(),scope:'Independent offline candidate-output tests; fixture source is not operational evidence',checks,checksPassed:checks.length,networkCalls,merchantPushPerformed:false};
 fs.writeFileSync(`${base}/review/MERCHANT-WRITE-INDEPENDENT-PROBES.json`,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report));
} finally {globalThis.fetch=savedFetch;fs.rmSync(dir,{recursive:true,force:true});}
